triggers.customTriggerLogic:
function (t)
   return t[1] and not t[2] and not t[3]
end

function (t)
   return t[1] and not t[2] and not t[3]
end

function (t)
   return t[1] and not t[2] and not t[3]
end

function (t)
    return (t[1] or t[2]) and not t[3]
end

function (t)
    return t[1] and t[2] and t[3]
end

function (t)
    return (t[1] or t[2]) and t[3]
end

function (t)
    return (t[1] or t[2]) and t[3]
end

function (t)
    return t[1] or t[2]
end
